// Detecta idioma del mensaje y devuelve el texto de WhatsApp correcto
const leadMsg = `{{webhook.lead_message}}`;
const name    = `{{webhook.contact_name}}`;
const barrio  = `{{webhook.property_neighborhood}}`;
const tipo    = `{{webhook.property_type}}`;
const phone   = `{{webhook.contact_phone}}`;

const englishWords = /\b(hello|hi|good\s(morning|afternoon|evening)|interested|available|apartment|flat|property|could\s(you|i)|would\s(like|be)|please|thank\s(you|s)|dear|sir|madam|we\s(are|would)|I\s(am|would)|looking\s(for|to))\b/i;
const spanishChars = /[áéíóúüñ¡¿]|\b(hola|gracias|buenos|buenas|estoy|tengo|quisiera|quiero|disponible|saber|interesado|inmueble|pareja|médico|colombiano|sería|podría|además|también|aparte|muchas|necesitas|presenta|nominas)\b/i;

const looksEnglish = englishWords.test(leadMsg);
const looksSpanish = spanishChars.test(leadMsg);
const lang = (looksEnglish && !looksSpanish) ? 'en' : 'es';

let message;
if (lang === 'en') {
  message = `Hi ${name}, how are you? 👋 You reached out about the property in *${barrio}* (${tipo}). What day would you like to visit? Can I give you a call?\n\nBest regards! 😊`;
} else {
  message = `Hola ${name} qué tal? Nos consultaste por el piso en *${barrio}* en ${tipo}, cuéntame qué día te gustaría visitarlo, ¿te puedo llamar por teléfono?\n\n¡Un saludo! 😊`;
}

return { lang, message, phone };
